"""Review representative frames for user-defined adjacent-frame groups."""
import json
from pathlib import Path
from addams_vlm_stream_probe import ROOT
OUT=ROOT/'docs/agents/raw/2026-10-30-addams-motion-groups-v1';manifest=json.loads((OUT/'manifest.json').read_text())
(OUT/'keyframe-template.json').write_text(json.dumps({'schema':'addams-motion-group-keyframe-review.v2','groups':manifest['groups'],'production_eligible':False},ensure_ascii=False,indent=2)+'\n')
items=[]
for g in manifest['groups']:
 for sf in g['representative_keyframes']:
  items.append(f'''<article><h2>{g["group_id"]} · 源{sf} · {(sf-1)/25:.2f}s</h2><p>组帧范围：{g["source_frames"][0]}–{g["source_frames"][-1]}</p><img src="../2026-10-29-addams-vlm-phase-test-v1/dense/frame-{sf:03}.jpg"><label>动作组语义<input data-g="{g["group_id"]}" data-f="{sf}" data-k="phase" value="{g["action_semantics"].get("phase","")}"></label><label>左脚关系<input data-g="{g["group_id"]}" data-f="{sf}" data-k="left_leg" value="{g["action_semantics"].get("left_leg","")}"></label><label>右脚关系<input data-g="{g["group_id"]}" data-f="{sf}" data-k="right_leg" value="{g["action_semantics"].get("right_leg","")}"></label><label>备注<textarea data-g="{g["group_id"]}" data-f="{sf}" data-k="notes"></textarea></label></article>''')
html='''<!doctype html><meta charset="utf-8"><title>动作组关键帧复核</title><style>body{background:#17191c;color:#eee;font:16px system-ui;margin:24px}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px}article{background:#24272b;padding:12px}img{width:100%}input,textarea{display:block;width:100%;box-sizing:border-box;background:#30343a;color:#fff;border:1px solid #555;margin:5px 0;padding:6px}button{padding:8px;margin:10px 5px 10px 0}</style><h1>第46–65帧 · 相邻动作组</h1><p>组边界已按用户指定：46–47、48–49、50–53、54–57、58–61、62–65。这里只复核每组代表帧，不逐帧识别；组间不继承语义。</p><button onclick="download()">下载组级JSON</button><div class="grid">'''+''.join(items)+'''</div><script>function download(){let rows=[...new Set([...document.querySelectorAll('[data-g]')].map(x=>x.dataset.g))].map(g=>{let fs=[...new Set([...document.querySelectorAll('[data-g="'+g+'"]')].map(x=>x.dataset.f))];return {group_id:g,keyframes:fs.map(f=>{let r={source_frame:+f};document.querySelectorAll('[data-g="'+g+'"][data-f="'+f+'"]').forEach(x=>r[x.dataset.k]=x.value);return r})}});let d={schema:'addams-motion-group-keyframe-review.v2',groups:rows,production_eligible:false};let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(d,null,2)],{type:'application/json'}));a.download='motion-groups-keyframes.json';a.click()}</script>'''
(OUT/'keyframe-review.html').write_text(html);print(OUT/'keyframe-review.html')
